import { Project } from '../../src'
import { servicenowFrontEndPlugins, rollup, glob } from '@servicenow/isomorphic-rollup'
import { path } from '@servicenow/sdk-build-core'

/**
 * End-to-end tests for cache busting functionality in UI builds.
 *
 * These tests use a minimal React fixture to verify that:
 * 1. The build pipeline adds (or omits) cache busting parameters based on configuration
 * 2. The UiPage transformation includes the correct script URLs in the XML output
 */
describe('UI Build Cache Busting - End to End', () => {
    const fixtureDir = path.resolve(__dirname, 'react-fixture')

    function cleanupFixture() {
        const distDir = path.join(fixtureDir, 'dist')
        if (require('fs').existsSync(distDir)) {
            require('fs').rmSync(distDir, { recursive: true, force: true })
        }

        const fluentDir = path.join(fixtureDir, 'src/fluent')
        if (require('fs').existsSync(fluentDir)) {
            require('fs').rmSync(fluentDir, { recursive: true, force: true })
        }
    }

    beforeEach(() => {
        cleanupFixture()
    })

    afterEach(() => {
        cleanupFixture()
    })

    async function runBuild(project: Project, enableCacheBusting: boolean) {
        const fs = project.getFileSystem()
        const config = project.getConfig()
        const rootDir = project.getRootDir()
        const clientDir = path.join(rootDir, config.clientDir)
        const registerExplicitId = project.registerExplicitId.bind(project)

        const htmlFilePattern = path.join(clientDir, '**', '*.html')
        const htmlFiles = await glob(htmlFilePattern, { fs })

        if (!htmlFiles.length) {
            throw new Error('No HTML files found')
        }

        const staticContentDir = path.join(rootDir, config.staticContentDir)
        fs.rmSync(staticContentDir, { recursive: true, force: true })

        const rollupBundle = await rollup({
            fs,
            input: htmlFilePattern,
            plugins: servicenowFrontEndPlugins({
                scope: config.scope,
                rootDir: clientDir,
                registerExplicitId,
                enableCacheBusting,
            }),
        })

        await rollupBundle.write({
            dir: staticContentDir,
            sourcemap: true,
        })
    }

    test('should add cache busting parameter when enableCacheBusting is true', async () => {
        const project = new Project({ rootDir: fixtureDir })
        project.registerExplicitId('sys_ui_page', 'test-page')

        await runBuild(project, true)

        const uiPageFile = project.addFile({
            path: 'src/fluent/test-page.now.ts',
            content: `import { UiPage } from '@servicenow/sdk/core'

UiPage({
    $id: Now.ID['test-page'],
    endpoint: 'x_test_app_test.do',
    html: Now.include('../../dist/static/index.html')
})`,
        })

        project.save()

        const output = await uiPageFile.getOutput()
        expect(output).toHaveLength(1)

        const xmlContent = output[0].content
        expect(xmlContent).toContain(
            '<script type="module" src="/uxasset/externals/x_test_app/app.jsdbx?uxpcb=$[UxFrameworkScriptables.getFlushTimestamp()]"></script>'
        )
    })

    test('should not add cache busting parameter when enableCacheBusting is false', async () => {
        const project = new Project({ rootDir: fixtureDir })
        project.registerExplicitId('sys_ui_page', 'test-page-no-cache')

        await runBuild(project, false)

        const uiPageFile = project.addFile({
            path: 'src/fluent/test-page-no-cache.now.ts',
            content: `import { UiPage } from '@servicenow/sdk/core'

UiPage({
    $id: Now.ID['test-page-no-cache'],
    endpoint: 'x_test_app_test_no_cache.do',
    html: Now.include('../../dist/static/index.html')
})`,
        })

        project.save()

        const output = await uiPageFile.getOutput()
        expect(output).toHaveLength(1)

        const xmlContent = output[0].content
        expect(xmlContent).toContain('<script type="module" src="/uxasset/externals/x_test_app/app.jsdbx"></script>')
    })
})
